-- Create "site_information" table
CREATE TABLE `site_information` (`id` int NOT NULL DEFAULT '1', `site_name` varchar(255) NOT NULL DEFAULT 'Kosatka CMS', `slogan` varchar(512) NOT NULL DEFAULT '', `site_email` varchar(255) NOT NULL DEFAULT '', `logo` varchar(255) NULL, `icon` varchar(255) NULL, `front_feed_view` varchar(64) NOT NULL DEFAULT '', `timezone` varchar(64) NULL, `default_language` varchar(12) NULL, `page_404` text NULL, `page_403` text NULL, `theme` varchar(64) NULL, `base_url` varchar(255) NULL, `robots_extra` text NULL, `languages` json NULL, `schema_org` json NULL, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "statistics_settings" table
CREATE TABLE `statistics_settings` (`id` int NOT NULL DEFAULT '1', `view_counting_enabled` bool NOT NULL DEFAULT true, `daily_views_keep_days` int unsigned NOT NULL DEFAULT 90, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "user_field_values" table
CREATE TABLE `user_field_values` (`id` int unsigned NOT NULL AUTO_INCREMENT, `user_id` int unsigned NOT NULL, `field_id` int unsigned NOT NULL, `value` text NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `user_field_values_user_field` (`user_id`, `field_id`), INDEX `user_field_values_field` (`field_id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "blocked_bots" table
CREATE TABLE `blocked_bots` (`id` int NOT NULL AUTO_INCREMENT, `pattern` varchar(255) NOT NULL, `comment` varchar(255) NULL, `created_at` datetime NOT NULL DEFAULT (CURRENT_TIMESTAMP), PRIMARY KEY (`id`), UNIQUE INDEX `blocked_bots_pattern` (`pattern`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "blocked_ips" table
CREATE TABLE `blocked_ips` (`id` int NOT NULL AUTO_INCREMENT, `ip` varchar(45) NOT NULL, `comment` varchar(255) NULL, `created_at` datetime NOT NULL DEFAULT (CURRENT_TIMESTAMP), PRIMARY KEY (`id`), UNIQUE INDEX `blocked_ips_ip` (`ip`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "user_fields" table
CREATE TABLE `user_fields` (`id` int unsigned NOT NULL AUTO_INCREMENT, `machine_name` varchar(64) NOT NULL, `label` varchar(255) NOT NULL, `max_len` int NOT NULL DEFAULT 255, `required` bool NOT NULL DEFAULT false, `weight` int NOT NULL DEFAULT 0, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `user_fields_machine_name` (`machine_name`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "captcha_settings" table
CREATE TABLE `captcha_settings` (`id` tinyint unsigned NOT NULL, `enabled` bool NOT NULL DEFAULT true, `site_key` varchar(255) NOT NULL DEFAULT '', `secret_key` varchar(512) NOT NULL DEFAULT '', `on_login` bool NOT NULL DEFAULT true, `on_register` bool NOT NULL DEFAULT true, `on_password` bool NOT NULL DEFAULT true, `module_forms` text NOT NULL, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "upload_settings" table
CREATE TABLE `upload_settings` (`id` int unsigned NOT NULL, `max_file_size_bytes` int NOT NULL, `max_image_dimension` int NOT NULL, `allowed_mime_types` varchar(255) NOT NULL, `user_file_extensions` varchar(500) NOT NULL DEFAULT 'pdf doc docx xls xlsx ppt pptx odt ods odp txt rtf csv zip', PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "comment_settings" table
CREATE TABLE `comment_settings` (`id` int NOT NULL DEFAULT '1', `new_author_checks` bigint NOT NULL DEFAULT 1, `links_limit` bigint NOT NULL DEFAULT 2, `stop_words` text NULL, `stop_words_action` varchar(16) NOT NULL DEFAULT 'hold', `duplicate_hours` bigint NOT NULL DEFAULT 24, `spam_keep_days` bigint NOT NULL DEFAULT 30, `bot_trap` bool NOT NULL DEFAULT true, `bot_min_seconds` bigint NOT NULL DEFAULT 3, `load_with_page` bool NOT NULL DEFAULT true, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "theme_settings" table
CREATE TABLE `theme_settings` (`id` bigint NOT NULL AUTO_INCREMENT, `theme` varchar(64) NOT NULL, `data` json NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `theme` (`theme`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "maintenance_settings" table
CREATE TABLE `maintenance_settings` (`id` int NOT NULL DEFAULT '1', `enabled` bool NOT NULL DEFAULT false, `message` text NOT NULL, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "text_formats" table
CREATE TABLE `text_formats` (`id` int unsigned NOT NULL AUTO_INCREMENT, `machine_name` varchar(64) NOT NULL, `label` varchar(255) NOT NULL, `weight` int NOT NULL DEFAULT 0, `allowed_tags` mediumtext NULL, `allow_class_attribute` bool NOT NULL DEFAULT false, `has_rich_editor` bool NOT NULL DEFAULT true, `tinymce_plugins` mediumtext NULL, `tinymce_toolbar` mediumtext NULL, `allowed_extensions` varchar(255) NOT NULL DEFAULT '', `max_file_size_bytes` int NOT NULL DEFAULT 0, `status` int NOT NULL DEFAULT 1, `filters` varchar(255) NOT NULL DEFAULT '', `created_by` int unsigned NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `machine_name` (`machine_name`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "blocks" table
