-- Create "account_settings" table
CREATE TABLE `account_settings` (`id` int NOT NULL DEFAULT '1', `registration_mode` varchar(32) NOT NULL DEFAULT 'visitors', `require_email_verification` bool NOT NULL DEFAULT false, `user_timezones` bool NOT NULL DEFAULT false, `subj_welcome_admin` varchar(512) NOT NULL DEFAULT '', `body_welcome_admin` mediumtext NOT NULL, `subj_welcome_pending` varchar(512) NOT NULL DEFAULT '', `body_welcome_pending` mediumtext NOT NULL, `subj_welcome_open` varchar(512) NOT NULL DEFAULT '', `body_welcome_open` mediumtext NOT NULL, `subj_activation` varchar(512) NOT NULL DEFAULT '', `body_activation` mediumtext NOT NULL, `subj_password_reset` varchar(512) NOT NULL DEFAULT '', `body_password_reset` mediumtext NOT NULL, `subj_email_confirm` varchar(512) NOT NULL DEFAULT '', `body_email_confirm` mediumtext NOT NULL, `subj_admin_notify` varchar(512) NOT NULL DEFAULT '', `body_admin_notify` mediumtext NOT NULL, `registration_blocked_domains` text NOT NULL, `avatar_allowed_extensions` varchar(255) NOT NULL DEFAULT '', `avatar_max_file_size_bytes` int NOT NULL DEFAULT 0, `two_factor_roles` json NULL, `two_factor_issuer` varchar(100) NOT NULL DEFAULT '', `cancel_content` varchar(16) NOT NULL DEFAULT 'keep', PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "seo_templates" table
CREATE TABLE `seo_templates` (`scope` varchar(80) NOT NULL, `title_template` varchar(512) NOT NULL DEFAULT '', `description_template` varchar(512) NOT NULL DEFAULT '', `image_template` varchar(512) NOT NULL DEFAULT '', `schema_type` varchar(64) NOT NULL DEFAULT '', `schema_props` json NULL, PRIMARY KEY (`scope`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "search_settings" table
CREATE TABLE `search_settings` (`id` int unsigned NOT NULL, `placeholder_image` varchar(255) NOT NULL DEFAULT '', `categories_menu` varchar(64) NOT NULL DEFAULT '', PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "redirects" table
