-- Create "modules" table
CREATE TABLE `modules` (`name` varchar(64) NOT NULL, `enabled` bool NOT NULL DEFAULT true, `updated_at` datetime NOT NULL DEFAULT (CURRENT_TIMESTAMP), PRIMARY KEY (`name`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "mail_settings" table
CREATE TABLE `mail_settings` (`id` tinyint unsigned NOT NULL, `enabled` bool NOT NULL DEFAULT true, `transport` varchar(16) NOT NULL DEFAULT '', `from_address` varchar(255) NOT NULL DEFAULT '', `resend_api_key` varchar(512) NOT NULL DEFAULT '', `smtp_host` varchar(255) NOT NULL DEFAULT '', `smtp_port` int NOT NULL DEFAULT 0, `smtp_user` varchar(255) NOT NULL DEFAULT '', `smtp_password` varchar(512) NOT NULL DEFAULT '', `log_keep_days` int unsigned NOT NULL DEFAULT 30, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "date_formats" table
