-- Create "mail_log" table
CREATE TABLE `mail_log` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `sent_at` datetime NOT NULL, `mail_key` varchar(128) NOT NULL DEFAULT '', `recipient` varchar(255) NOT NULL, `subject` varchar(512) NOT NULL DEFAULT '', `status` varchar(16) NOT NULL, `error` varchar(1024) NOT NULL DEFAULT '', PRIMARY KEY (`id`), INDEX `idx_mail_log_sent_at` (`sent_at`), INDEX `idx_mail_log_mail_key_sent_at` (`mail_key`, `sent_at`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "interface_strings" table
