-- Create "image_styles" table
CREATE TABLE `image_styles` (`id` int unsigned NOT NULL AUTO_INCREMENT, `name` varchar(64) NOT NULL, `label` varchar(255) NOT NULL, `description` varchar(255) NULL, `width` int NOT NULL, `height` int NOT NULL DEFAULT 0, `mode` varchar(20) NOT NULL, `anchor` varchar(20) NOT NULL DEFAULT 'center', `quality` int NOT NULL DEFAULT 85, `format` varchar(8) NOT NULL DEFAULT 'webp', `hidpi` bool NOT NULL DEFAULT false, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `name` (`name`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
