-- Create "view_displays" table
CREATE TABLE `view_displays` (`id` int unsigned NOT NULL AUTO_INCREMENT, `base_entity` varchar(16) NOT NULL DEFAULT 'content', `is_default` bool NOT NULL DEFAULT false, `override_settings` bool NOT NULL DEFAULT false, `override_filters` bool NOT NULL DEFAULT false, `override_sort` bool NOT NULL DEFAULT false, `override_fields` bool NOT NULL DEFAULT false, `machine_name` varchar(64) NOT NULL, `label` varchar(255) NOT NULL, `meta_title` varchar(255) NULL, `meta_description` mediumtext NULL, `url_path` varchar(255) NULL, `display_type` varchar(10) NOT NULL DEFAULT 'page', `attach_content_types` varchar(255) NULL, `attach_weight` int NOT NULL DEFAULT 0, `term_vocabularies` varchar(255) NOT NULL DEFAULT '', `profile_tab_path` varchar(64) NOT NULL DEFAULT '', `profile_tab_access` varchar(16) NOT NULL DEFAULT 'all', `theme_template` varchar(64) NOT NULL DEFAULT '', `attach_title` varchar(255) NULL, `attach_show_title` bool NOT NULL DEFAULT true, `display_style` varchar(10) NOT NULL DEFAULT 'grid', `grid_columns` int NOT NULL DEFAULT 5, `overflow_after` int NOT NULL DEFAULT 0, `carousel_slides_per_view` int NOT NULL DEFAULT 1, `carousel_autoplay` bool NOT NULL DEFAULT false, `carousel_loop` bool NOT NULL DEFAULT false, `carousel_show_navigation` bool NOT NULL DEFAULT true, `carousel_show_pagination` bool NOT NULL DEFAULT true, `carousel_effect` varchar(10) NOT NULL DEFAULT 'slide', `show_pagination` bool NOT NULL DEFAULT true, `pagination_ajax` bool NOT NULL DEFAULT false, `show_glossary` bool NOT NULL DEFAULT false, `page_size` int NOT NULL DEFAULT 30, `header_text` mediumtext NULL, `footer_text` mediumtext NULL, `overflow_header_text` varchar(255) NULL, `custom_css` mediumtext NULL, `row_template` mediumtext NULL, `group_by_field` varchar(64) NULL, `group_date_format` varchar(8) NULL, `published_snapshot` mediumtext NULL, `published_at` datetime NULL, `status` tinyint NOT NULL DEFAULT 1, `created_by` int unsigned NOT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `view_id` int unsigned NULL, `glossary_field_storage_id` int unsigned NULL, `carousel_link_field_storage_id` int unsigned NULL, PRIMARY KEY (`id`), UNIQUE INDEX `machine_name` (`machine_name`), UNIQUE INDEX `url_path` (`url_path`), INDEX `viewdisplaydef_carousel_link_field_storage_id` (`carousel_link_field_storage_id`), INDEX `viewdisplaydef_glossary_field_storage_id` (`glossary_field_storage_id`), INDEX `viewdisplaydef_view_id` (`view_id`), CONSTRAINT `view_displays_views_view` FOREIGN KEY (`view_id`) REFERENCES `views` (`id`) ON DELETE CASCADE, CONSTRAINT `view_displays_field_storages_glossary_field_storage` FOREIGN KEY (`glossary_field_storage_id`) REFERENCES `field_storages` (`id`) ON DELETE NO ACTION, CONSTRAINT `view_displays_field_storages_carousel_link_field_storage` FOREIGN KEY (`carousel_link_field_storage_id`) REFERENCES `field_storages` (`id`) ON DELETE NO ACTION) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "menus" table
