CREATE TABLE `block_placements` (`id` int unsigned NOT NULL AUTO_INCREMENT, `placement_type` varchar(16) NOT NULL DEFAULT 'custom', `plugin_id` varchar(32) NULL, `plugin_config` json NULL, `menu_start_level` int NOT NULL DEFAULT 1, `menu_levels_to_show` int NOT NULL DEFAULT 0, `title` varchar(255) NULL, `show_title` bool NOT NULL DEFAULT false, `theme` varchar(64) NOT NULL DEFAULT 'default', `region` varchar(64) NOT NULL, `weight` int NOT NULL DEFAULT 0, `visibility_scope` varchar(16) NOT NULL DEFAULT 'all', `visibility_content_type` varchar(255) NULL, `visibility_pages` mediumtext NULL, `visibility_pages_mode` varchar(8) NOT NULL DEFAULT 'show', `visibility_roles` varchar(512) NOT NULL DEFAULT '', `lazy` bool NOT NULL DEFAULT false, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `block_id` int unsigned NULL, `view_display_id` int unsigned NULL, `menu_id` int unsigned NULL, PRIMARY KEY (`id`), INDEX `idx_block_placements_theme_region` (`theme`, `region`), INDEX `blockplacementdef_block_id` (`block_id`), INDEX `blockplacementdef_menu_id` (`menu_id`), INDEX `blockplacementdef_view_display_id` (`view_display_id`), CONSTRAINT `block_placements_blocks_block` FOREIGN KEY (`block_id`) REFERENCES `blocks` (`id`) ON DELETE NO ACTION, CONSTRAINT `block_placements_view_displays_view_display` FOREIGN KEY (`view_display_id`) REFERENCES `view_displays` (`id`) ON DELETE CASCADE, CONSTRAINT `block_placements_menus_menu` FOREIGN KEY (`menu_id`) REFERENCES `menus` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "menu_links" table
CREATE TABLE `menu_links` (`id` int unsigned NOT NULL AUTO_INCREMENT, `title` varchar(255) NOT NULL, `link_type` varchar(16) NOT NULL DEFAULT 'url', `link_url` varchar(2048) NULL, `link_node_id` int unsigned NULL, `link_term_id` int unsigned NULL, `link_view_id` int unsigned NULL, `weight` int NOT NULL DEFAULT 0, `enabled` bool NOT NULL DEFAULT true, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `menu_id` int unsigned NOT NULL, `parent_id` int unsigned NULL, PRIMARY KEY (`id`), INDEX `menulinkdef_menu_id` (`menu_id`), INDEX `menulinkdef_parent_id` (`parent_id`), CONSTRAINT `menu_links_menus_menu` FOREIGN KEY (`menu_id`) REFERENCES `menus` (`id`) ON DELETE NO ACTION, CONSTRAINT `menu_links_menu_links_parent` FOREIGN KEY (`parent_id`) REFERENCES `menu_links` (`id`) ON DELETE SET NULL) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "breadcrumb_rules" table
