-- Create "users" table
CREATE TABLE `users` (`id` int unsigned NOT NULL AUTO_INCREMENT, `username` varchar(255) NOT NULL, `slug` varchar(255) NOT NULL, `avatar` varchar(255) NULL, `email` varchar(255) NULL, `password_hash` varchar(255) NOT NULL, `timezone` varchar(64) NULL, `metadata` json NULL, `signature` mediumtext NULL, `status` int NULL DEFAULT 1, `email_verified` bool NULL DEFAULT false, `session_version` int NOT NULL DEFAULT 0, `accessed_at` timestamp NULL, `created_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `updated_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `role_id` int NULL, PRIMARY KEY (`id`), INDEX `idx_users_accessed_at` (`accessed_at`), UNIQUE INDEX `idx_users_email` (`email`), UNIQUE INDEX `alias` (`slug`), UNIQUE INDEX `username` (`username`), INDEX `user_role_id` (`role_id`), CONSTRAINT `users_roles_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE SET NULL) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "nodes" table
CREATE TABLE `nodes` (`id` int unsigned NOT NULL AUTO_INCREMENT, `type` varchar(100) NOT NULL, `title` varchar(255) NOT NULL, `slug` varchar(255) NULL, `status` bool NOT NULL DEFAULT '0', `on_moderation` bool NOT NULL DEFAULT 0, `comment_mode` varchar(10) NOT NULL DEFAULT 'open', `path_auto` bool NOT NULL DEFAULT false, `promote` bool NOT NULL DEFAULT false, `sticky` bool NOT NULL DEFAULT false, `view_roles` varchar(1024) NOT NULL DEFAULT '', `publish_on` datetime NULL, `unpublish_on` datetime NULL, `deleted_at` datetime NULL, `deleted_by` bigint NULL, `langcode` varchar(12) NOT NULL DEFAULT '', `created_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `updated_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `created_by` int unsigned NULL, `parent_id` int unsigned NULL, PRIMARY KEY (`id`), UNIQUE INDEX `slug` (`slug`), INDEX `idx_nodes_status_moderation_created` (`status`, `on_moderation`, `created_at`, `id`), INDEX `idx_nodes_status_mod_type` (`status`, `on_moderation`, `type`), INDEX `idx_nodes_type_status_created` (`type`, `status`, `created_at`), INDEX `idx_nodes_promote_status_sticky_created` (`promote`, `status`, `sticky`, `created_at`), INDEX `idx_nodes_publish_on` (`publish_on`), INDEX `idx_nodes_unpublish_on` (`unpublish_on`), INDEX `idx_nodes_parent` (`parent_id`), INDEX `idx_nodes_deleted_at` (`deleted_at`), INDEX `idx_nodes_langcode` (`langcode`), INDEX `node_created_by` (`created_by`), CONSTRAINT `nodes_users_users` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL, CONSTRAINT `nodes_nodes_block_items` FOREIGN KEY (`parent_id`) REFERENCES `nodes` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "comments" table
CREATE TABLE `comments` (`id` int unsigned NOT NULL AUTO_INCREMENT, `subject` varchar(255) NULL, `content` mediumtext NOT NULL, `created_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `updated_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `status` bool NOT NULL DEFAULT 1, `path` varchar(500) NULL, `hold_reason` varchar(255) NOT NULL DEFAULT '', `nid` int unsigned NOT NULL, `created_by` int unsigned NOT NULL, `parent_id` int unsigned NULL, PRIMARY KEY (`id`), INDEX `comment_created_by` (`created_by`), INDEX `comment_parent_id` (`parent_id`), INDEX `comment_created_at` (`created_at`), INDEX `comment_nid_status_path` (`nid`, `status`, `path`), INDEX `comment_status_created_at` (`status`, `created_at`), CONSTRAINT `comments_nodes_node` FOREIGN KEY (`nid`) REFERENCES `nodes` (`id`) ON DELETE CASCADE, CONSTRAINT `comments_users_author` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `comments_comments_parent` FOREIGN KEY (`parent_id`) REFERENCES `comments` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "content_types" table
