CREATE TABLE `user_oauth_identities` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `provider` varchar(16) NOT NULL, `provider_user_id` varchar(128) NOT NULL, `email` varchar(255) NULL, `created_at` datetime NOT NULL, `user_id` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `useroauthidentity_provider_provider_user_id` (`provider`, `provider_user_id`), INDEX `useroauthidentity_user_id_provider` (`user_id`, `provider`), CONSTRAINT `user_oauth_identities_users_oauth_identities` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "user_recovery_codes" table
CREATE TABLE `user_recovery_codes` (`id` int unsigned NOT NULL AUTO_INCREMENT, `code_hash` char(64) NOT NULL, `used_at` datetime NULL, `user_id` int unsigned NOT NULL, PRIMARY KEY (`id`), INDEX `idx_user_recovery_codes_user` (`user_id`, `code_hash`), CONSTRAINT `user_recovery_codes_users_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "user_two_factor" table
CREATE TABLE `user_two_factor` (`id` int unsigned NOT NULL AUTO_INCREMENT, `secret` varchar(255) NOT NULL, `last_step` bigint NOT NULL DEFAULT 0, `enabled_at` datetime NOT NULL, `user_id` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `idx_user_two_factor_user` (`user_id`), CONSTRAINT `user_two_factor_users_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "view_fields" table
CREATE TABLE `view_fields` (`id` int unsigned NOT NULL AUTO_INCREMENT, `builtin_field` varchar(32) NULL, `label` varchar(255) NOT NULL, `show_label` bool NOT NULL DEFAULT true, `image_style` varchar(64) NULL, `date_format` varchar(64) NULL, `tag_format` varchar(20) NULL, `image_display` varchar(10) NULL, `formatter` varchar(64) NULL, `layout` varchar(16) NULL, `link_to` varchar(20) NULL, `css_class` varchar(255) NULL, `rewrite_html` mediumtext NULL, `trim_length` int NOT NULL DEFAULT 0, `sort_order` int NOT NULL DEFAULT 0, `exclude_from_display` bool NOT NULL DEFAULT false, `hide_in_overflow` bool NOT NULL DEFAULT false, `fallback_field_key` varchar(64) NULL, `params` json NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `view_display_id` int unsigned NOT NULL, `field_storage_id` int unsigned NULL, PRIMARY KEY (`id`), INDEX `idx_view_fields_view_sort` (`view_display_id`, `sort_order`), INDEX `viewfielddef_field_storage_id` (`field_storage_id`), CONSTRAINT `view_fields_view_displays_view_display` FOREIGN KEY (`view_display_id`) REFERENCES `view_displays` (`id`) ON DELETE CASCADE, CONSTRAINT `view_fields_field_storages_field_storage` FOREIGN KEY (`field_storage_id`) REFERENCES `field_storages` (`id`) ON DELETE NO ACTION) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "view_filters" table
CREATE TABLE `view_filters` (`id` int unsigned NOT NULL AUTO_INCREMENT, `builtin_field` varchar(32) NULL, `operator` varchar(32) NOT NULL, `value` mediumtext NULL, `value_is_relative` bool NOT NULL DEFAULT false, `exposed` bool NOT NULL DEFAULT false, `exposed_param` varchar(64) NULL, `exposed_label` varchar(255) NULL, `contextual` bool NOT NULL DEFAULT false, `sort_order` int NOT NULL DEFAULT 0, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `view_display_id` int unsigned NOT NULL, `field_storage_id` int unsigned NULL, `via_field_storage_id` int unsigned NULL, PRIMARY KEY (`id`), INDEX `idx_view_filters_view_sort` (`view_display_id`, `sort_order`), INDEX `viewfilterdef_field_storage_id` (`field_storage_id`), INDEX `viewfilterdef_via_field_storage_id` (`via_field_storage_id`), CONSTRAINT `view_filters_view_displays_view_display` FOREIGN KEY (`view_display_id`) REFERENCES `view_displays` (`id`) ON DELETE CASCADE, CONSTRAINT `view_filters_field_storages_field_storage` FOREIGN KEY (`field_storage_id`) REFERENCES `field_storages` (`id`) ON DELETE NO ACTION, CONSTRAINT `view_filters_field_storages_via_field_storage` FOREIGN KEY (`via_field_storage_id`) REFERENCES `field_storages` (`id`) ON DELETE NO ACTION) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "view_sorts" table
CREATE TABLE `view_sorts` (`id` int unsigned NOT NULL AUTO_INCREMENT, `builtin_field` varchar(32) NULL, `direction` varchar(4) NOT NULL DEFAULT 'desc', `sort_order` int NOT NULL DEFAULT 0, `params` json NULL, `exposed_key` varchar(64) NOT NULL DEFAULT '', `exposed_label` varchar(255) NOT NULL DEFAULT '', `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `view_display_id` int unsigned NOT NULL, `field_storage_id` int unsigned NULL, PRIMARY KEY (`id`), INDEX `idx_view_sorts_view_sort` (`view_display_id`, `sort_order`), INDEX `viewsortdef_field_storage_id` (`field_storage_id`), CONSTRAINT `view_sorts_view_displays_view_display` FOREIGN KEY (`view_display_id`) REFERENCES `view_displays` (`id`) ON DELETE CASCADE, CONSTRAINT `view_sorts_field_storages_field_storage` FOREIGN KEY (`field_storage_id`) REFERENCES `field_storages` (`id`) ON DELETE NO ACTION) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
